class Solution {
    public void nextPermutation(int[] nums) {
        for(int i = nums.length-1;i>=0;i--){
            if(i==0){
                Arrays.sort(nums);
                return;
            }
            if(nums[i-1]<nums[i]){
                Arrays.sort(nums,i,nums.length);
                for(int j = i;j<nums.length;j++){
                    if(nums[j]>nums[i-1]){
                        swap(nums,j,i-1);
                        return;
                    }
                }
            }
        }
    }
    public void swap(int[]nums,int a,int b){
        int temp = nums[a];
        nums[a] = nums[b];
        nums[b] = temp;
    }
}
